document.getElementById('appleExample').onclick=async()=>{try{const raw=atob(WHITEFORM_APPLE.src.split(',')[1]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));importQueue=[];$('importMode').value='image';$('iw').value=64;$('ih').value=64;$('colorLimit').value=24;await loadImportImage(new File([bytes],WHITEFORM_APPLE.name,{type:'image/jpeg'}));$('importMode').value='image';sourceDraw();updateConversionPreview();notice('苹果原图已载入：默认64×64、最多24色，确认后可逐格修改。');}catch(error){notice('示例载入失败：'+error.message);}};
